import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

/**
 * Built-in alarm sounds. The WAV files are generated by tools/make_sounds.py
 * (synthesised from scratch, public domain), and the ids here must match the
 * <option> values in ui/timer-dial.html.
 */
export const BUILT_IN_SOUNDS = [
	"soft-pulse",
	"gentle-chime",
	"sonar",
	"classic-beeper",
	"digital-watch",
	"desk-bell",
	"rise-and-shine",
	"retro-arcade",
	"alarm-clock",
] as const;

export type BuiltInSound = (typeof BUILT_IN_SOUNDS)[number];
export const DEFAULT_SOUND: BuiltInSound = "classic-beeper";
export const CUSTOM_SOUND = "custom";

/**
 * The bundled plugin lives at <plugin>.sdPlugin/bin/plugin.js, so the sounds
 * folder is one level up. Resolving from `import.meta.url` (this file's own
 * location) is more reliable than relying on the process's working directory.
 */
const SOUNDS_DIR = fileURLToPath(new URL("../sounds/", import.meta.url));

function isBuiltIn(id: string | undefined): id is BuiltInSound {
	return !!id && (BUILT_IN_SOUNDS as readonly string[]).includes(id);
}

/**
 * Works out which file to play.
 * @param sound The chosen sound id (or "custom").
 * @param customPaths Candidate paths for a custom file, best first. The embedded
 *        resource path comes first because Stream Deck rewrites it when a
 *        profile is imported on another computer.
 */
export function resolveSoundFile(sound: string | undefined, customPaths: Array<string | undefined>): string {
	if (sound === CUSTOM_SOUND) {
		const custom = customPaths.find((p) => p && existsSync(p));
		if (custom) return custom;
		// Fall through: a missing custom file should still ring *something*.
	}
	return path.join(SOUNDS_DIR, `${isBuiltIn(sound) ? sound : DEFAULT_SOUND}.wav`);
}
